# -*- coding: utf-8 -*-
"""cost_payers_r126.py -- the costed table of the addendum's payers (R126, 2026-09-20): for each payer A1 to A8 (and the Figure 2 row label), the body
with that one payer reverted is built in place and the fine number read (reviews/v22/tools/fine.py), so each payer's cost in lines stands beside the
aggregate. The body is regenerated by port_v22.py at the end, so nothing this script writes survives it. Each reversal is an asserted replacement of the
payer's new text by the inbox's (or v21's) text it replaced. Usage: python reviews/v22/tools/cost_payers_r126.py
"""
from __future__ import annotations

import io
import pathlib
import re
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parents[3]
TOOLS = ROOT / "reviews" / "v22" / "tools"
BODY = ROOT / "reviews" / "v22" / "src" / "body_v22.tex"
sys.path.insert(0, str(TOOLS))
import port_v22 as P  # noqa: E402


def fine():
    out = subprocess.run([sys.executable, str(TOOLS / "fine.py")], capture_output=True, text=True).stdout
    m = re.search(r"main-text-end page (\d+); fine number (\d+)", out)
    return int(m.group(1)), int(m.group(2))


def cut(text, start, end):
    i = text.index(start); j = text.index(end, i) + len(end)
    return text[i:j]


def main():
    subprocess.run([sys.executable, str(TOOLS / "port_v22.py")], check=True, capture_output=True)
    base = BODY.read_text(encoding="utf-8")
    page0, fine0 = fine()
    b21 = P.rd(P.V21B)
    _, fig1, def1, grid, fig2, census, tail = P.v21_pieces(b21)
    old_fig1 = P.fig1_v22(fig1)
    variants = {
        "A1 Figure 1 (the inbox's three boxes for our adapted v21 TikZ)": (cut(base, "\\begin{figure}[t]\n\\centering\n%% R126 addendum A1", "\\end{figure}\n"), old_fig1),
        "A2 Table 2's caption": ("\\caption{Backend census: counts of disagreement with the manifest-and-alignment reference, without hand adjudication or sampling intervals. Lower panel: coverage losses and rebuilt-summary scores. (Appendices~\\ref{app:inversion} and~\\ref{app:census})}",
                                 "\\caption{Backend census against the manifests. Counts of disagreement with the manifest-and-alignment reference, without hand adjudication; no sampling intervals. FR-Bank's retained assertions depend on the stored-versus-obsolete matching threshold; its conflation of retraction with supersession is in Appendix~\\ref{app:census}. The artifact's \\texttt{repro\\_mem0\\_erase.py} and \\texttt{repro\\_amem\\_links.py} reproduce the Mem0 and A-MEM rows. Lower panel: coverage losses and rebuilt-summary scores (Appendix~\\ref{app:inversion}).}"),
        "A3 Section 6's first paragraph": ("FR-Bank marks about $58$ times as many entries stale as ground truth, yet retains obsolete assertions as active and conflates retraction with supersession.\n"
                                           "Mem0 overwrites at the retrieval surface we evaluated, and A-MEM's links resolve to no note in our integration (Table~\\ref{tab:census}). (Appendix~\\ref{app:census})\n",
                                           "FR-Bank's census marks about $58$ times as many entries stale as ground truth, yet retains obsolete assertions as active.\n"
                                           "It also conflates retraction with supersession.\n"
                                           "Mem0 overwrites at the retrieval surface we evaluated (\\texttt{search} and \\texttt{get\\_all}, \\texttt{mem0ai} 1.0.5); its per-memory history call was not consulted.\n"
                                           "A-MEM's links fail to resolve to note identifiers in our integration.\n"
                                           "Table~\\ref{tab:census} gives the census and matching scope. (Appendix~\\ref{app:census})\n"),
        "A4 Definition 1's intent clause and the hike paragraph's last two sentences": ("a question about a past event can license the expired event.\n",
                                                                                       "a question about a past event can license the expired event. The construction never labels a change question \\pn{}. Definition~\\ref{def:coverage} lists the combinations the construction defines.\n"),
        "A5 Section 3's two summary-size sentences (to E.3)": ("%% R126 addendum A5 (2026-09-20): the two summary-size sentences moved to Appendix E.3.\nThe summary route reads",
                                                               "Summary size grows with categories, states and distinct names; at a fixed vocabulary, it does not grow with record count. Counts remain because the design fixed them before the study. The summary route reads"),
        "A6 the long-or-wrong-lists paragraph": ("On the full obligation set, padding the default list to $60$ names lowers the lookup to $0.67$, and mini falls with it; on the counterfactual set, injecting wrong names lowers mini, Haiku and the lookup together.\n"
                                                 "Not every decline is reliable, and short ground-truth lists do not establish robustness to longer store-written lists. (Appendix~\\ref{app:counterfactual})\n",
                                                 "On the full obligation set, padding the default list lowers the lookup to $0.67$ at $60$ names; mini also falls.\n"
                                                 "Not every decline is reliable, and short ground-truth lists do not establish robustness to longer store-written lists.\n"
                                                 "On the counterfactual set, injecting wrong names also lowers mini, Haiku and the lookup together.\n"
                                                 "At the larger tested injection rate, neither model exceeds that lookup by more than $0.02$, and neither margin is reliable. (Appendix~\\ref{app:counterfactual})\n"),
        "A7 the Haiku paragraph (to E.9) and the FR-Bank paragraph's last sentence": ("Haiku retains more of its gain than mini does, and more where the target's name survives the store's list ($0.87$ against $0.68$ where it does not; descriptive). (Appendix~\\ref{app:census})\n",
                                                                                     "Haiku retains more of its gain than mini does. (Appendix~\\ref{app:census})\n\n"
                                                                                     "\\claim{Haiku fares better when FR-Bank keeps the target name.}\n"
                                                                                     "With the uncapped store-written summary, Haiku scores $0.87$ on supersession obligations whose name survives, against $0.89$ under ground truth.\n"
                                                                                     "Where the name is missing, its store-written score is $0.68$.\n"
                                                                                     "This descriptive split resembles the target-name ablation, but the missing-name subgroup is small and its paired decline is not reliable. (Appendix~\\ref{app:census})\n"),
        "A8 Section 7's first two paragraphs merged": ("Mini scores $0.73$ with the default summary, $0.69$ with the retrieved records and their ground-truth tags, and a reliable $0.83$ with both.\n"
                                                       "The two routes mirror each other by state: against the summary alone, the view gains mini $0.24$ on expiry and costs it $0.17$ on supersession, both reliable.\n"
                                                       "Haiku's score with both stays within tolerance of its summary alone. (Appendix~\\ref{app:resp})\n",
                                                       "Mini scores $0.73$ with the default summary and $0.69$ with the retrieved records and their ground-truth tags.\n"
                                                       "Combining them raises its score reliably to $0.83$.\n"
                                                       "(Appendix~\\ref{app:resp})\n\n"
                                                       "\\claim{The view helps mini on expiry but hurts on supersession.}\n"
                                                       "Compared with the summary alone, mini gains $0.24$ on expiry and loses $0.17$ on supersession; both differences are reliable.\n"
                                                       "For Haiku, combining the view and summary scores $0.79$, below its summary-only $0.82$, though within tolerance.\n"
                                                       "(Appendix~\\ref{app:resp})\n"),
        "Figure 2's second row label (the inbox's, for v21's with the category name)": ("category: entries, active, retracted &", "category (\\texttt{PROJECTS\\_ENDEAVORS}): entries, active, retracted &"),
    }
    rows = []
    for name, (new, old) in variants.items():
        assert base.count(new) == 1, (name, base.count(new))
        io.open(BODY, "w", encoding="utf-8", newline="\n").write(base.replace(new, old))
        page, f = fine()
        rows.append((name, page, f, f - fine0))
        print(f"{name:80s} page {page} fine {f} ({f - fine0:+d} against the landed {fine0})")
    subprocess.run([sys.executable, str(TOOLS / "port_v22.py")], check=True, capture_output=True)
    page1, fine1 = fine()
    assert (page1, fine1) == (page0, fine0)
    out = ["| payer reverted | page | fine number | lines the payer pays |", "|---|---:|---:|---:|"]
    out += [f"| {n} | {p} | {f} | {d:+d} |" for n, p, f, d in rows]
    out.append(f"| all applied (as landed) | {page0} | {fine0} | (before the addendum: page 10, fine number 501) |")
    (ROOT / "reviews" / "v22" / "results" / "cost_payers_r126.md").write_text("\n".join(out) + "\n", encoding="utf-8", newline="\n")
    print("\n".join(out))


if __name__ == "__main__":
    main()
